// Extracts DESIGN Appendix B's test-int/harness.ts into packages/xrpl/test-int/ and applies the two known fixes
// (the earlier happy.int.ts flow is NOT written: full-flow.int.test.ts replaced it, issue I-2.5-a):
//   1. default import of xrpl (named ESM imports such as ECDSA fail under plain Node);
//   2. when a transaction is rejected before it is applied (tem/tef/tel), report engine_result instead of undefined.
// Run: node scripts/extract-harness.ts   (from packages/xrpl). Overwrites the generated files.
import { readFileSync, writeFileSync } from 'node:fs';

const design = readFileSync(new URL('../../../DESIGN.md', import.meta.url), 'utf8');
const appendix = design.slice(design.indexOf('## Appendix B'), design.indexOf('## Appendix C'));

function block(title: string): string {
  const start = appendix.indexOf(`### ${title}`);
  const open = appendix.indexOf('```ts\n', start);
  const close = appendix.indexOf('\n```', open + 6);
  if (start < 0 || open < 0 || close < 0) throw new Error(`Appendix B block not found: ${title}`);
  return appendix.slice(open + 6, close + 1);
}

function replaceOnce(src: string, from: string, to: string): string {
  if (!src.includes(from)) throw new Error(`expected text not found: ${from}`);
  return src.replace(from, to);
}

let harness = block('test-int/harness.ts');
harness = replaceOnce(
  harness,
  "import { Client, Wallet, ECDSA, multisign, SubmittableTransaction } from 'xrpl';",
  "import xrpl from 'xrpl';\nimport type { Client, SubmittableTransaction, Wallet } from 'xrpl';",
);
harness = replaceOnce(
  harness,
  "Wallet.fromSeed('snoPBrXtMeMyMHUVTgbuqAfg1SUTb', { algorithm: ECDSA.secp256k1 })",
  "xrpl.Wallet.fromSeed('snoPBrXtMeMyMHUVTgbuqAfg1SUTb', { algorithm: xrpl.ECDSA.secp256k1 })",
);
harness = replaceOnce(harness, 'multisign(blobs)', 'xrpl.multisign(blobs)');
harness = replaceOnce(harness, 'Wallet.generate(ECDSA.ed25519)', 'xrpl.Wallet.generate(xrpl.ECDSA.ed25519)');
harness = replaceOnce(
  harness,
  "  const out: any = await client.request({ command: 'tx', transaction: hash } as any);\n  return { engine: res.result.engine_result, final: out.result.meta?.TransactionResult as string, hash, seq: res.result.tx_json.Sequence };",
  "  // A tx rejected before it is applied (tem, tef, tel) is never in a ledger: report engine_result, not undefined.\n  const out: any = await client.request({ command: 'tx', transaction: hash } as any).catch(() => undefined);\n  const engine = res.result.engine_result;\n  return { engine, final: (out?.result.meta?.TransactionResult as string | undefined) ?? engine, hash, seq: res.result.tx_json.Sequence };",
);

const out = (name: string) => new URL(`../test-int/${name}`, import.meta.url);
const header =
  '// biome-ignore-all lint: generated by scripts/extract-harness.ts from DESIGN Appendix B\n// biome-ignore-all format: generated\n';
writeFileSync(out('harness.ts'), header + harness);
